// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAgents List agents as trees, by project name, then name
	// (GET /v1/agents)
	ListAgents(w http.ResponseWriter, r *http.Request, params ListAgentsParams)
	// CreateAgent Create an agent and start its AI coding agent
	// (POST /v1/agents)
	CreateAgent(w http.ResponseWriter, r *http.Request)
	// DeleteAgent Delete an agent
	// (DELETE /v1/agents/{agent})
	DeleteAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params DeleteAgentParams)
	// GetAgent An agent, in any state
	// (GET /v1/agents/{agent})
	GetAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params GetAgentParams)
	// UpdateAgent Rename an agent
	// (PATCH /v1/agents/{agent})
	UpdateAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params UpdateAgentParams)
	// GetAgentHistory Lines of an agent's history, in any state
	// (GET /v1/agents/{agent}/history)
	GetAgentHistory(w http.ResponseWriter, r *http.Request, agent AgentRef, params GetAgentHistoryParams)
	// RestartAgent Start an agent again in a new session, which reads its history in brief
	// (POST /v1/agents/{agent}/restart)
	RestartAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params RestartAgentParams)
	// SendAgent Queue a message for a running agent
	// (POST /v1/agents/{agent}/send)
	SendAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params SendAgentParams)
	// StartAgent Start an agent whose AI coding agent ended, in the same session
	// (POST /v1/agents/{agent}/start)
	StartAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params StartAgentParams)
	// GetAgentTranscript Lines of an agent's conversation as text, in any state
	// (GET /v1/agents/{agent}/transcript)
	GetAgentTranscript(w http.ResponseWriter, r *http.Request, agent AgentRef, params GetAgentTranscriptParams)
	// GetDaemon The daemon serving this socket
	// (GET /v1/daemon)
	GetDaemon(w http.ResponseWriter, r *http.Request)
	// ReloadDaemon Read the settings again and apply them
	// (POST /v1/daemon/reload)
	ReloadDaemon(w http.ResponseWriter, r *http.Request)
	// ListDocs List a project's docs by name
	// (GET /v1/docs)
	ListDocs(w http.ResponseWriter, r *http.Request, params ListDocsParams)
	// CreateDoc Create a doc at revision 1
	// (POST /v1/docs)
	CreateDoc(w http.ResponseWriter, r *http.Request)
	// SyncDocsToGit Write a project's docs, read-only, into a directory of its repository
	// (POST /v1/docs/sync-to-git)
	SyncDocsToGit(w http.ResponseWriter, r *http.Request)
	// DeleteDoc Delete a doc, its revisions and its copies on disk
	// (DELETE /v1/docs/{doc})
	DeleteDoc(w http.ResponseWriter, r *http.Request, doc DocRef, params DeleteDocParams)
	// GetDoc A doc with one revision's content, the latest by default
	// (GET /v1/docs/{doc})
	GetDoc(w http.ResponseWriter, r *http.Request, doc DocRef, params GetDocParams)
	// UpdateDoc Change a doc's status or labels, or rename it
	// (PATCH /v1/docs/{doc})
	UpdateDoc(w http.ResponseWriter, r *http.Request, doc DocRef, params UpdateDocParams)
	// UpdateDocContent Write a doc's content as a new revision, if base is still its latest
	// (PUT /v1/docs/{doc}/content)
	UpdateDocContent(w http.ResponseWriter, r *http.Request, doc DocRef, params UpdateDocContentParams)
	// ListDocRevisions A doc's revisions, latest first, without content
	// (GET /v1/docs/{doc}/revisions)
	ListDocRevisions(w http.ResponseWriter, r *http.Request, doc DocRef, params ListDocRevisionsParams)
	// OpenEditor Start the editor the editor setting names on a file of a worktree
	// (POST /v1/editors)
	OpenEditor(w http.ResponseWriter, r *http.Request)
	// ListMessages List a project's messages still waiting, oldest first
	// (GET /v1/messages)
	ListMessages(w http.ResponseWriter, r *http.Request, params ListMessagesParams)
	// DiscardMessage Discard a message still waiting
	// (DELETE /v1/messages/{message})
	DiscardMessage(w http.ResponseWriter, r *http.Request, message string)
	// ResendMessage Send a message still waiting to its terminal or agent, as it is now
	// (POST /v1/messages/{message}/resend)
	ResendMessage(w http.ResponseWriter, r *http.Request, message string)
	// ListPlans List a project's plans by name
	// (GET /v1/plans)
	ListPlans(w http.ResponseWriter, r *http.Request, params ListPlansParams)
	// CreatePlan Create a plan at revision 1, checked and reduced
	// (POST /v1/plans)
	CreatePlan(w http.ResponseWriter, r *http.Request)
	// DeletePlan Delete a plan, its revisions and its copy on disk
	// (DELETE /v1/plans/{plan})
	DeletePlan(w http.ResponseWriter, r *http.Request, plan PlanRef, params DeletePlanParams)
	// GetPlan A plan with one revision's content and what it defines, the latest by default
	// (GET /v1/plans/{plan})
	GetPlan(w http.ResponseWriter, r *http.Request, plan PlanRef, params GetPlanParams)
	// UpdatePlan Rename a plan
	// (PATCH /v1/plans/{plan})
	UpdatePlan(w http.ResponseWriter, r *http.Request, plan PlanRef, params UpdatePlanParams)
	// UpdatePlanContent Write a plan's content as a new revision, checked and reduced, if base is still its latest
	// (PUT /v1/plans/{plan}/content)
	UpdatePlanContent(w http.ResponseWriter, r *http.Request, plan PlanRef, params UpdatePlanContentParams)
	// ListPlanRevisions A plan's revisions, latest first, without content
	// (GET /v1/plans/{plan}/revisions)
	ListPlanRevisions(w http.ResponseWriter, r *http.Request, plan PlanRef, params ListPlanRevisionsParams)
	// RunPlan Run a draft plan of tasks
	// (POST /v1/plans/{plan}/run)
	RunPlan(w http.ResponseWriter, r *http.Request, plan PlanRef, params RunPlanParams)
	// FinishPlanTask Say a running task is done, with a summary, so that it lands on the plan's branch
	// (POST /v1/plans/{plan}/tasks/{task}/done)
	FinishPlanTask(w http.ResponseWriter, r *http.Request, plan PlanRef, task string, params FinishPlanTaskParams)
	// ListProjects List projects, without their worktrees, sorted by name
	// (GET /v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// CreateProject Create a project or open a git repository as one
	// (POST /v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject Delete a project and everything that belongs to it
	// (DELETE /v1/projects/{project})
	DeleteProject(w http.ResponseWriter, r *http.Request, project ProjectRef, params DeleteProjectParams)
	// GetProject A project, open or closed, with which of its checkouts are on disk and its terminals and agents
	// (GET /v1/projects/{project})
	GetProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// UpdateProject Close a project, or open it again from one of its checkouts
	// (PATCH /v1/projects/{project})
	UpdateProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// StreamProject Follow a project, sent whole every time it changes
	// (GET /v1/projects/{project}/events)
	StreamProject(w http.ResponseWriter, r *http.Request, project ProjectRef, params StreamProjectParams)
	// GetProjectLanding How a project lands its worktrees
	// (GET /v1/projects/{project}/landing)
	GetProjectLanding(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// SetProjectLanding Set how a project lands its worktrees
	// (PUT /v1/projects/{project}/landing)
	SetProjectLanding(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// ReplaceTabs Replace the tabs tide has open in a project
	// (PUT /v1/projects/{project}/tabs)
	ReplaceTabs(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// GetProjectView Read what tide shows of a project besides its tabs
	// (GET /v1/projects/{project}/view)
	GetProjectView(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// ReplaceProjectView Replace what tide shows of a project besides its tabs
	// (PUT /v1/projects/{project}/view)
	ReplaceProjectView(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// RecloneProject Clone a project with no checkout left back into its clone path
	// (POST /v1/projects/{project}/worktrees)
	RecloneProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// RefreshWorktrees Read the "worktree_statuses" of a project's streams again now
	// (POST /v1/projects/{project}/worktrees/refresh)
	RefreshWorktrees(w http.ResponseWriter, r *http.Request, project ProjectRef, params RefreshWorktreesParams)
	// ListSettings Every setting, with its value in the config file now
	// (GET /v1/settings)
	ListSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSetting Change a setting and apply it at once
	// (PATCH /v1/settings/{setting})
	UpdateSetting(w http.ResponseWriter, r *http.Request, setting string)
	// ListTerminals List terminals by project name, then name
	// (GET /v1/terminals)
	ListTerminals(w http.ResponseWriter, r *http.Request, params ListTerminalsParams)
	// CreateTerminal Create a terminal and start its shell
	// (POST /v1/terminals)
	CreateTerminal(w http.ResponseWriter, r *http.Request)
	// DeleteTerminal Delete a terminal
	// (DELETE /v1/terminals/{terminal})
	DeleteTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params DeleteTerminalParams)
	// GetTerminal A terminal, in any state
	// (GET /v1/terminals/{terminal})
	GetTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params GetTerminalParams)
	// GetTerminalHistory Lines of a terminal's history, in any state
	// (GET /v1/terminals/{terminal}/history)
	GetTerminalHistory(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params GetTerminalHistoryParams)
	// SendTerminal Queue a message for a running terminal's shell
	// (POST /v1/terminals/{terminal}/send)
	SendTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params SendTerminalParams)
	// StartTerminal Start a fresh shell for a terminal whose last one ended
	// (POST /v1/terminals/{terminal}/start)
	StartTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params StartTerminalParams)
	// GetTideView Read what tide shows as a whole, such as the project shown
	// (GET /v1/tide/view)
	GetTideView(w http.ResponseWriter, r *http.Request)
	// ReplaceTideView Replace what tide shows as a whole
	// (PUT /v1/tide/view)
	ReplaceTideView(w http.ResponseWriter, r *http.Request)
	// GetVersion Version of the daemon
	// (GET /v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
	// ListWorktrees List every checkout git lists for a project, with its changes
	// (GET /v1/worktrees)
	ListWorktrees(w http.ResponseWriter, r *http.Request, params ListWorktreesParams)
	// RemoveWorktree Remove a worktree that landed
	// (DELETE /v1/worktrees/{worktree})
	RemoveWorktree(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params RemoveWorktreeParams)
	// ListWorktreeComments List a worktree's comments in every state, by file and line
	// (GET /v1/worktrees/{worktree}/comments)
	ListWorktreeComments(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params ListWorktreeCommentsParams)
	// CreateWorktreeComment Save a comment on a line of a diff, not sent until its review is
	// (POST /v1/worktrees/{worktree}/comments)
	CreateWorktreeComment(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params CreateWorktreeCommentParams)
	// DeleteWorktreeComment Delete a comment not sent yet
	// (DELETE /v1/worktrees/{worktree}/comments/{comment})
	DeleteWorktreeComment(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, comment string, params DeleteWorktreeCommentParams)
	// EditWorktreeComment Change the text of a comment not sent yet
	// (PATCH /v1/worktrees/{worktree}/comments/{comment})
	EditWorktreeComment(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, comment string, params EditWorktreeCommentParams)
	// GetWorktreeDiff What a worktree has committed since it left its base, as a PR shows it, or what it has not committed
	// (GET /v1/worktrees/{worktree}/diff)
	GetWorktreeDiff(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params GetWorktreeDiffParams)
	// RemoveWorktreeFile Delete a file, or a directory with all it holds, from a worktree
	// (DELETE /v1/worktrees/{worktree}/files)
	RemoveWorktreeFile(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params RemoveWorktreeFileParams)
	// ListWorktreeFiles The files of a worktree, tracked and untracked, without gitignored ones
	// (GET /v1/worktrees/{worktree}/files)
	ListWorktreeFiles(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params ListWorktreeFilesParams)
	// RenameWorktreeFile Rename a file or directory of a worktree, in its directory
	// (PATCH /v1/worktrees/{worktree}/files)
	RenameWorktreeFile(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params RenameWorktreeFileParams)
	// CreateWorktreeFile Create an empty file or directory in a worktree
	// (POST /v1/worktrees/{worktree}/files)
	CreateWorktreeFile(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params CreateWorktreeFileParams)
	// GetWorktreeFileContent What a file of a worktree holds now, on disk
	// (GET /v1/worktrees/{worktree}/files/content)
	GetWorktreeFileContent(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params GetWorktreeFileContentParams)
	// GetWorktreeFileDiff The uncommitted changes of a file, with all of its lines
	// (GET /v1/worktrees/{worktree}/files/diff)
	GetWorktreeFileDiff(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params GetWorktreeFileDiffParams)
	// UnverifyWorktreeFile Take a file's verified mark away
	// (DELETE /v1/worktrees/{worktree}/files/verified)
	UnverifyWorktreeFile(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params UnverifyWorktreeFileParams)
	// VerifyWorktreeFile Mark a file verified
	// (PUT /v1/worktrees/{worktree}/files/verified)
	VerifyWorktreeFile(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params VerifyWorktreeFileParams)
	// LandWorktree Start landing a worktree on its base
	// (POST /v1/worktrees/{worktree}/land)
	LandWorktree(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params LandWorktreeParams)
	// SendWorktreeReview Send a worktree's comments not sent yet to an agent, as one message
	// (POST /v1/worktrees/{worktree}/reviews)
	SendWorktreeReview(w http.ResponseWriter, r *http.Request, worktree WorktreeRef, params SendWorktreeReviewParams)
}

